[SubscribesTo(classStr(JournalStatic), staticDelegateStr(JournalStatic,findJournalTableIdDelegate))]
public static void findJournalTableIdDelegateImpl(
    TableId             _tableId,
    JournalId           _journalId,
    boolean             _forUpdate,
    EventHandlerResult  _result)
{
    if (_tableId == tableNum(UPSPriceTermJournalTable) && _journalId)
    {
        UPSPriceTermJournalTable journalTable = UPSPriceTermJournalTable::find(_journalId, _forUpdate);
        _result.result(journalTable);
    }
}
